import{_ as a,c as e,o as t,a4 as o}from"./chunks/framework.4aTu-Nia.js";const D=JSON.parse('{"title":"CDN","description":"","frontmatter":{},"headers":[],"relativePath":"web/cdn.md","filePath":"web/cdn.md"}'),i={name:"web/cdn.md"},l=o('<h1 id="cdn" tabindex="-1">CDN <a class="header-anchor" href="#cdn" aria-label="Permalink to &quot;CDN&quot;">​</a></h1><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2><blockquote><p>如何判定使用哪个服务 IP就近、存在内容、负载情况、服务能力</p></blockquote><p>最简单的CDN网络由一个DNS服务器和几台缓存服务器组成：</p><ol><li><p>当用户点击网站页面上的内容URL，经过本地DNS系统解析，DNS系统会最终将域名的解析权交给CNAME指向的CDN专用DNS服务器。</p></li><li><p>CDN的DNS服务器将CDN的全局负载均衡设备IP地址返回给用户</p></li><li><p>用户向CDN的全局负载均衡设备发起内容URL访问请求</p></li><li><p>CDN全局负载均衡设备根据用户IP地址，以及用户请求的内容URL，选择一台用户所属区域的区域负载均衡设备，告诉用户向这台设备发起请求 区域负载均衡设备会为用户选择一台合适的缓存服务器提供服务，选择的依据包括：根据用户IP地址，判断哪一台服务器距用户最近；根据用户所请求的URL中携带的内容名称，判断哪一台服务器上有用户所需内容；查询各个服务器当前的负载情况，判断哪一台服务器尚有服务能力。基于以上这些条件的综合分析之后，区域负载均衡设备会向全局负载均衡设备返回一台缓存服务器的IP地址</p></li><li><p>全局负载均衡设备把服务器的IP地址返回给用户用户向缓存服务器发起请求，缓存服务器响应用户请求，将用户所需内容传送到用户终端。如果这台缓存服务器上并没有用户想要的内容，而区域均衡设备依然将它分配给了用户，那么这台服务器就要向它的上一级缓存服务器请求内容，直至追溯到网站的源服务器将内容拉到本地</p></li></ol>',6),r=[l];function c(n,d,s,_,p,h){return t(),e("div",null,r)}const u=a(i,[["render",c]]);export{D as __pageData,u as default};
